import React, { useContext } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Web3Context } from '../contexts/Web3Context';

const Navbar = () => {
  const { currentAccount, connectWallet, balance } = useContext(Web3Context);
  const location = useLocation();

  const isActive = (path) => location.pathname === path ? "text-white bg-white/10" : "text-gray-400 hover:text-white";

  return (
    <nav className="fixed top-0 w-full z-50 border-b border-white/5 bg-[#0B0E14]/80 backdrop-blur-md">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        {/* Logo */}
        <Link to="/" className="flex items-center gap-2">
          <div className="w-8 h-8 bg-gradient-to-tr from-indigo-500 to-pink-500 rounded-lg"></div>
          <span className="text-xl font-bold font-heading tracking-wide text-white">
            Web3<span className="text-indigo-400">Learn</span>
          </span>
        </Link>

        {/* Menu */}
        <div className="hidden md:flex gap-2">
          {['/market', '/create', '/dashboard'].map((path) => (
            <Link 
              key={path} 
              to={path} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${isActive(path)}`}
            >
              {path === '/market' ? 'Sàn Thử Thách' : path === '/create' ? 'Creator Studio' : 'BXH'}
            </Link>
          ))}
        </div>

        {/* Wallet */}
        {currentAccount ? (
          <div className="flex items-center gap-4">
            <div className="hidden md:flex flex-col items-end mr-2">
              <span className="text-[10px] uppercase tracking-wider text-gray-500 font-bold">Balance</span>
              <span className="text-sm font-mono text-emerald-400 font-bold">{parseFloat(balance).toFixed(4)} ETH</span>
            </div>
            <Link to="/profile" className="group relative">
              <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-gray-800 to-gray-900 border border-white/10 flex items-center justify-center text-indigo-400 font-bold shadow-lg group-hover:border-indigo-500/50 transition-all">
                {currentAccount.slice(2, 4)}
              </div>
              <div className="absolute top-0 right-0 h-3 w-3 bg-green-500 rounded-full border-2 border-[#0B0E14]"></div>
            </Link>
          </div>
        ) : (
          <button onClick={connectWallet} className="btn-primary py-2 px-6 text-sm">
            Kết Nối Ví
          </button>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
